// Bundles wiki/*.md into src/wikiData.ts so the app has every page offline. Runs before builds (npm run wiki).
const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, '..', 'wiki');
const index = JSON.parse(fs.readFileSync(path.join(dir, 'index.json'), 'utf8'));
const pages = {};
for (const p of index.pages) pages[p.id] = fs.readFileSync(path.join(dir, p.id + '.md'), 'utf8');
const out = `// Generated by scripts/bundle-wiki.js from wiki/. Do not edit by hand.\nexport const WIKI_INDEX = ${JSON.stringify(index, null, 1)};\nexport const WIKI_PAGES: Record<string, string> = ${JSON.stringify(pages, null, 1)};\n`;
fs.writeFileSync(path.join(__dirname, '..', 'src', 'wikiData.ts'), out);
console.log('wiki: bundled', Object.keys(pages).length, 'pages');
